"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3439],{3396(a){a.exports=JSON.parse('{"title":"\ucd94\uc0c1\ud654\ub294 \uc801\uc808\ud558\uac8c & \uc9c4\ud654\ud558\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c","date":"2024-04-10","coverUrl":null,"html":"<h2 data-notion-block-id=\\"ec85017c-c8bc-46e1-abbe-e69801686efa\\" id=\\"ec85017c-c8bc-46e1-abbe-e69801686efa\\">\ucd94\uc0c1\ud654\ub294 \uc801\uc808\ud558\uac8c</h2><a href=\\"https://blog.jim-nielsen.com/2024/expose-platform-apis-over-wrapping-them/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.jim-nielsen.com/2024/expose-platform-apis-over-wrapping-them/</a><p data-notion-block-id=\\"4c1eb20e-3585-4381-8747-e3828930a15a\\"><b>\uc2ec\uc724\uc12d</b>: \ucd94\uc0c1\ud654\ub97c \uc801\uc808\ud558\uac8c \ud558\uc5ec \uac16\ub294 \uc774\uc810\uc744 \uc18c\uac1c\ud558\ub294 \ub450 \uae00\uc785\ub2c8\ub2e4. <s>\uccab \uae00\uc740 React Native \ubaa8\ub4c8\uc744 \ub9cc\ub4e4 \uacbd\uc6b0 \ub124\uc774\ud2f0\ube0c\uc5d0 \uac00\uae30 \uc804\uc5d0 \ucd94\uc0c1\ud654(\ud0c0\uc785 \uac80\uc0ac \ubc0f \uac80\uc99d)\ub97c \ud574\uc11c \uc131\ub2a5\uc0c1 \uc774\uc810\uc744 \uac00\uc838\uc624\uac70\ub098 \uc2a4\ud0c0\uc77c API\ub97c CSS\uc640 \ube44\uc2b7\ud558\uac8c \ucd94\uc0c1\ud654\ud558\uc5ec \uac1c\ubc1c\uc758 \uc6a9\uc774\uc131\uc744 \uac00\uc838\uc654\ub2e4\ub294 \uc608\uc2dc\ub97c \ub4e4\uace0 \uc788\uc2b5\ub2c8\ub2e4</s>(\uc0ad\uc81c\ub418\uc5c8\uc2b5\ub2c8\ub2e4). \ub450\ubc88\uc9f8 \uae00\uc740 Next.js\uac00 \ud50c\ub7ab\ud3fc API\uc640 \ube44\uc2b7\ud558\uac8c \uad6c\uc131\ud558\uc9c0 \uc54a\uace0 \uc784\uc758\ub85c \ub798\ud551\ud574\uc11c \ud5a5\ud6c4\uc5d0 \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc774 \uc0dd\uacbc\uc744 \uacbd\uc6b0\ub098 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ubc14\uafc0 \uacbd\uc6b0\ub97c \ub300\ube44\ud558\uae30 \ud798\ub4e4\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc801\uc808\ud55c \ucd94\uc0c1\ud654\uac00 \uc720\uc9c0\ubcf4\uc218 \uce21\uba74\uc5d0\uc11c \uc88b\ub2e4\ub77c\ub294 \uac83\uc744 \uc8fc\uc7a5\ud558\uace0 \uc788\uc9c0\ub9cc(\uccab\ubc88\uc9f8 \uae00\uc5d0\uc11c\ub294 RN \ubaa8\ub4c8\uc744 \ub9cc\ub4e4 \ub54c \uade0\ud615\uc744 \ud1b5\ud574 Android\ub098 iOS\uc758 \ucf54\ub4dc\uac00 \ubc14\ub00c\uc5c8\uc744 \ub54c \uc27d\uac8c \ubcc0\uacbd\ud560 \uc218 \uc788\ub2e4, \ub450\ubc88\uc9f8 \uae00\uc5d0\uc11c\ub294 HTML API\uc640 \ube44\uc2b7\ud558\uac8c \ub9cc\ub4e4\uc5b4\uc57c \ub098\uc911\uc5d0 API \uba85\uc138\uac00 \ubc14\ub00c\uac70\ub098 \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\ub85c \uad50\uccb4\ud558\uae30 \uc27d\ub2e4).. \uc5b4\ub835\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"3d0f4c17-e121-48f6-a400-a3f1c92d803f\\"><b>\uae40\ub300\uad00: </b>\uc815\ud655\ud558\uac8c \ub85c\uc6b0 \ub808\ubca8\uc5d0\uc11c\uc758 \ub3d9\uc791\uae4c\uc9c0\ub294 \uc544\ub2c8\ub77c\ub3c4 \uc5b4\ub290\uc815\ub3c4\uc758 \uae30\uc220\uc758 \ub3d9\uc791\uc744 \uc774\ud574\ud55c\ub2e4\uba74 \ucd94\uc0c1\ud654\ub97c \ud1b5\ud574 \uc720\uc9c0\ubcf4\uc218\uc758 \ud3b8\ub9ac\uc131\uc5d0 \uc27d\uac8c \uc811\uadfc\ud560 \uc218 \uc788\uc744 \uac83\uc785\ub2c8\ub2e4. \ucd94\uc0c1\ud654\uc5d0 \ub300\ud55c \uc811\uadfc\ub3c4 \uc88b\uc9c0\ub9cc, \uba3c\uc800 \uae30\uc220\uc744 \uc774\ud574\ud558\uace0 \uc788\ub294\uc9c0\ub97c \ud655\uc778\ud558\uace0 \ucd94\uc0c1\ud654\ub97c \uc2dc\ub3c4\ud558\ub294 \uac83\uc774 \uc880 \ub354 \uc88b\uc740 \uc811\uadfc\uc774 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"db3ef69e-93d7-422a-a3e0-d5816a79be50\\" id=\\"db3ef69e-93d7-422a-a3e0-d5816a79be50\\">\uc9c4\ud654\ud558\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c</h2><a href=\\"https://engineering.atspotify.com/2021/04/customization-vs-configuration-in-evolving-design-systems/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://engineering.atspotify.com/2021/04/customization-vs-configuration-in-evolving-design-systems/</a><a href=\\"https://engineering.atspotify.com/2023/05/multiple-layers-of-abstraction-in-design-systems/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://engineering.atspotify.com/2023/05/multiple-layers-of-abstraction-in-design-systems/</a><p data-notion-block-id=\\"78a961d8-29c2-4503-9c69-a07dbb4a0b2e\\"><b>\uc2ec\uc724\uc12d</b>: \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0 \ub300\ud55c <a href=\\"https://blog.notifly.tech/notifly-design-system/\\">\uae00</a>\uc774 \uc774\ubaa9\uc744 \ub04c\uc5b4\uc11c Spotify \ube14\ub85c\uadf8\uc5d0\uc11c \uc124\uba85\ud558\ub294 \ucd94\uc0c1\ud654 \ub2e8\uacc4\uc640 \uadf8 \uc7a5\ub2e8\uc810\uc744 \uc124\uba85\ud558\ub294 \uae00\uc744 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ucd5c\uadfc <a href=\\"https://fe-developers.kakaoent.com/2022/220731-composition-component/\\">\ud569\uc131 \ucef4\ud3ec\ub10c\ud2b8\ub77c\ub294 \uc811\uadfc \ubc29\uc2dd</a>\uc774 \uc774\ubaa9\uc744 \ub04c\uc5c8\uc9c0\ub9cc \uc2e4\uc81c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc740 \uc774 \uc811\uadfc \ubc29\uc2dd\uc774 \ud544\uc694 \uc5c6\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c Spotify\ub294 <a href=\\"https://spotify.design/article/a-design-system-isnt-one-size-fits-all\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ub610\ud55c \uc81c\ud488</a>\uc774\ub77c\uace0 \uc124\uba85\ud558\uba74\uc11c \uc870\uc9c1\uc758 \ud2b9\uc5d0 \ub530\ub77c \uc801\uc6a9\ud558\uae30\ub97c \ubc14\ub77c\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f7949d83-8084-4a55-a043-3dc70c6c0151\\" id=\\"f7949d83-8084-4a55-a043-3dc70c6c0151\\">RN \ubc84\uc804\uc744 \ud56d\uc0c1 \ucd5c\uc2e0\ud654\ud574\uc57c \ud558\ub294 \uc774\uc720</h2><a href=\\"https://www.callstack.com/blog/always-run-the-latest-version-of-react-native\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/always-run-the-latest-version-of-react-native</a><p data-notion-block-id=\\"ac6a735b-b078-46e9-9c6c-c453b1c6097b\\"><b>\uc2ec\uc724\uc12d</b>: RN\uc5d0\uc11c \ubcf4\uc548\ud328\uce58\uc640 Android / iOS\uc758 \ucd5c\uc2e0 \ubcc0\uacbd\uc0ac\ud56d\uc744 \uc720\uc9c0\ud558\uae30 \uc704\ud574 \ucd5c\uc2e0\ud654\ud574\uc57c \ud55c\ub2e4\ub294 \uac83\uacfc \uc5b4\ub5bb\uac8c \ucd5c\uc2e0 \ubc84\uc804\uc744 \uc720\uc9c0\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc6f9 \ubd80\ubd84\uc5d0\uc11c\ub3c4 \uc5b4\ub5bb\uac8c \ucd5c\uc2e0 \ubc84\uc804\uc744 \uc720\uc9c0\ud574\uc57c \ud560\uc9c0 \uace0\ubbfc\ud558\ub294 \uac83\ub3c4 \uc0dd\uac01\ud574\ubd10\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"d92f293c-c611-4b54-8514-4a4c1bc12270\\" id=\\"d92f293c-c611-4b54-8514-4a4c1bc12270\\">\uc27d\uac8c \uc774\ubbf8\uc9c0 \ucd5c\uc801\ud654\ud558\uae30</h2><a href=\\"https://blog.sentry.io/low-effort-image-optimization-tips/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.sentry.io/low-effort-image-optimization-tips/</a><p data-notion-block-id=\\"1a57ad5f-6f3a-4cd9-93b5-97c4883c472a\\"><b>\uc2ec\uc724\uc12d</b>: \uc6f9 \uc131\ub2a5 \ucd5c\uc801\ud654\ub97c \uc704\ud574 \ud56d\uc0c1 \ub530\ub77c\uc624\ub294 \uc774\ubbf8\uc9c0 \ucd5c\uc801\ud654\ub294 \uc5b4\ub5bb\uac8c \ud574\uc694?\uc5d0 \ub300\ud55c \ub2f5\uc744 \uc815\ub9ac\ud574\ub193\uc740 Sentry\uc758 \ube14\ub85c\uadf8\uc785\ub2c8\ub2e4. \ube4c\ub4dc \uc2dc \ucd5c\uc801\ud654, \uc694\uccad \uc2dc \ucd5c\uc801\ud654, \ud0c0\uc0ac \uc11c\ube44\uc2a4 \uc774\uc6a9\uc744 \uc801\uc5b4\ub193\uc558\uc2b5\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c \ud0c0\uc0ac \uc11c\ube44\uc2a4\ub294 \ube44\uc6a9 \ub54c\ubb38(Vercel \uac00\uaca9\uc740 \uc0c1\uc0c1\uc744 \ucd08\uc6d4\ud55c\ub2e4)\uc5d0 \uc81c\uccd0\ub450\uba74 \uc815\uc801\uc77c \uacbd\uc6b0(SSG, \ud639\uc740 \uc624\ub7ab\ub3d9\uc548 \ubc14\ub00c\uc9c0 \uc54a\uc744 \uc694\uc18c)\uc758 \ube4c\ub4dc \uc2dc \ucd5c\uc801\ud654, \ub3d9\uc801\uc77c \uacbd\uc6b0\uc758 \uc694\uccad \uc2dc \ucd5c\uc801\ud654(\ud6c4 \uc800\uc7a5, \uce90\uc2dc \uae30\uac04 \uc124\uc815)\uc73c\ub85c \ub098\ub204\uc5b4\uc11c \uc0dd\uac01\ud574\ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"048b3fb2-2ed5-4a72-a1f3-f03ff1c4d842\\"><b>\uae40\ub300\uad00: </b>\uc6f9\uc5d0\uc11c \ud558\ub098\uc758 \ud398\uc774\uc9c0\uc5d0 \uc218\uc2ed \uc218\ubc31\uac1c\uc758 \uc774\ubbf8\uc9c0\ub97c \ub85c\ub529\ud558\uac8c \ub41c\ub2e4\uba74 \ub85c\ub529\uc2dc\uac04\uc774 \ud655 \ub298\uc5b4\ub098\uae30 \ub9c8\ub828\uc785\ub2c8\ub2e4. \uc5ec\ub7ec \ucd5c\uc801\ud654 \ubc29\uc2dd\uacfc \ub354\ubd88\uc5b4\uc11c \uc911\uac04 LCP \uc131\ub2a5\uc744 \uc704\ud574 \uc548\ubcf4\uc774\ub294 \uc774\ubbf8\uc9c0\ub97c Lazy Loading \ud558\ub294 \uac83\ub3c4 \uc0ac\uc6a9\uc790\uc5d0\uac8c \uc88b\uc740 \uc0ac\uc6a9\uc131\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\uc73c\ub2c8 \uc798 \uc77d\uc5b4\ubcf4\uc2dc\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"3a9d735e-131f-4633-9ef9-ad9b85ae2020\\" id=\\"3a9d735e-131f-4633-9ef9-ad9b85ae2020\\">Container Query \uc27d\uac8c \uc774\ud574\ud558\uae30</h2><a href=\\"https://ishadeed.com/article/css-container-query-guide\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/css-container-query-guide</a><p data-notion-block-id=\\"bcd461d1-4716-4e3c-9071-3e3aefdd8066\\">\ubc18\uc751\ud615 \ub514\uc790\uc778\uc744 \ub2e4\uc591\ud55c \uc0c1\ud669\uc5d0 \ub300\uc751\ud560 \uc218 \uc788\ub3c4\ub85d, \uadf8\ub9ac\uace0 \ucf54\ub4dc\ub97c \ub354 \uc9c1\uad00\uc801\uc774\uac8c \ub9cc\ub4dc\ub294 Container Query\uc5d0 \ub300\ud55c \ub300\ud654\ud615 \uac00\uc774\ub4dc\uc785\ub2c8\ub2e4. Container Query\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c \ub2e4\uc591\ud55c \ube0c\ub77c\uc6b0\uc800\ub97c \ub300\uc751\ud574\uc57c \ud55c\ub2e4\uba74 <a href=\\"https://developer.chrome.com/blog/inside-the-container-query-polyfill?hl=ko\\">\ud3f4\ub9ac\ud544</a>\ub3c4 \uace0\ub824\ud574\ubd10\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f7bde14e-dd2b-4ba4-941d-2603c169161c\\" id=\\"f7bde14e-dd2b-4ba4-941d-2603c169161c\\">headless DnD</h2><a href=\\"https://github.com/atlassian/pragmatic-drag-and-drop?tab=readme-ov-file\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/atlassian/pragmatic-drag-and-drop?tab=readme-ov-file</a><p data-notion-block-id=\\"f14f27fb-8854-41b7-8d38-da161aa942ef\\">Drag and Drop\uc758 \ucf54\ub4dc\uc640 \ud328\ud0a4\uc9c0\ub97c \uacf5\uac1c\ud588\uc2b5\ub2c8\ub2e4. \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \uc885\uc18d\ub418\uc9c0 \uc54a\uc544 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc4f8\uc9c0\ub3c4 \ubaa8\ub974\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"b3476a56-0b24-42a0-b655-abe1c6283f73\\" id=\\"b3476a56-0b24-42a0-b655-abe1c6283f73\\">Vite\ub294 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub098\uc694?</h2><a href=\\"https://www.youtube.com/watch?v=M_edImKoEt8\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=M_edImKoEt8</a><p data-notion-block-id=\\"00625763-fae5-4d1d-9fa8-b8eea6632ad5\\">Vite \uc791\ub3d9\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c Diagram\uc73c\ub85c \uc124\uba85\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \ub0b4\uac00 \uc6d0\ud558\ub294 \uae30\ub2a5\uc744 \uad6c\ud604\ud558\ub824\uba74 \ub3d9\uc791 \ubc29\uc2dd\uc740 \uc778\uc9c0\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc5d0 \ub9ce\uc774 \uc0ac\uc6a9\ud558\uace0 \uc788\ub294 Vite\uc758 \ub3d9\uc791\ubc29\uc2dd\uc740 \uc54c\uace0 \uc788\uc73c\uba74 \uc88b\uc2b5\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"c0d8616e-52c1-482b-8471-6505d70f30e3\\" id=\\"c0d8616e-52c1-482b-8471-6505d70f30e3\\">CSS Inlining\uc758 \uc131\ub2a5 \ud5a5\uc0c1</h2><a href=\\"https://strikingloo.github.io/inlining-css\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://strikingloo.github.io/inlining-css</a><p data-notion-block-id=\\"419a6ddc-11be-41dd-bee2-46722edcc6fc\\">CSS Inlining\uc774 \uc131\ub2a5 \ud5a5\uc0c1\uc744 \uac00\uc838\uc628\ub2e4\ub294 \uc2e0\uae30\ud55c \uc0c1\ud669\uc744 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);